-- Six Philippine dish adaptations for catalogue variety. FNRI ingredient-input estimates; not allergy certification.
-- Raw input quantities avoid assuming that cooked weight equals purchased raw weight.
-- Idempotent: matching names are left unchanged. No existing recipes are edited.
BEGIN;
DO $seed$
DECLARE r jsonb; recipe_id_new text; missing integer;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($recipes$[{"id":"rcp-allergy-chicken-rice-porridge","name":"Chicken Rice Porridge","type":"Breakfast","cookTime":35,"dietTags":["dairy_free"],"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0776","name":"Chicken breast","grams":80,"quantity":"80 g before cooking"},{"fct_id":"1503","name":"Ginger","grams":5,"quantity":"5 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":50,"quantity":"50 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":3,"quantity":"3 g before cooking"}],"steps":[{"title":"Measure raw inputs","desc":"60 g Rice, well-milled; 80 g Chicken breast; 5 g Ginger; 50 g Carrot; 3 g Oil, coconut. Weigh these ingredients before cooking. Use only the listed ingredients and plain water."},{"title":"Prepare the meal","desc":"Simmer the measured rice, diced chicken breast, sliced ginger and carrot with about 450 ml plain water until the rice is soft and the chicken is fully cooked. Stir in the measured coconut oil. This is a simple lugaw adaptation."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is estimated from the weighed ingredient inputs; final cooked output has not been measured."},{"title":"Ingredient and allergy review","desc":"Research formulation awaiting nutritionist review. Check supplier labels and avoid cross-contact during preparation. This recipe is not certified allergen-free or medically approved. Unlisted additions require a new ingredient check."},{"title":"Poultry handling","desc":"Keep uncooked poultry separate from ready-to-eat food, wash hands and utensils after handling, and cook the chicken thoroughly before serving."}]},{"id":"rcp-allergy-ginger-chicken-and-chayote-with-rice","name":"Ginger Chicken and Chayote with Rice","type":"Lunch","cookTime":35,"dietTags":["dairy_free"],"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":75,"quantity":"75 g before cooking"},{"fct_id":"0776","name":"Chicken breast","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0323","name":"Chayote fruit","grams":120,"quantity":"120 g before cooking"},{"fct_id":"1503","name":"Ginger","grams":8,"quantity":"8 g before cooking"},{"fct_id":"0409","name":"Onion, Bombay bulb","grams":20,"quantity":"20 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":5,"quantity":"5 g before cooking"}],"steps":[{"title":"Measure raw inputs","desc":"75 g Rice, well-milled; 100 g Chicken breast; 120 g Chayote fruit; 8 g Ginger; 20 g Onion, Bombay bulb; 5 g Oil, coconut. Weigh these ingredients before cooking. Use only the listed ingredients and plain water."},{"title":"Prepare the meal","desc":"Cook the measured dry rice separately in plain water. Warm the oil and soften the onion and ginger. Add diced chicken breast, chayote and enough plain water to simmer. Cook until the chicken is fully cooked and the chayote is tender. Serve with all of the rice. This is a tinola adaptation."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is estimated from the weighed ingredient inputs; final cooked output has not been measured."},{"title":"Ingredient and allergy review","desc":"Research formulation awaiting nutritionist review. Check supplier labels and avoid cross-contact during preparation. This recipe is not certified allergen-free or medically approved. Unlisted additions require a new ingredient check."},{"title":"Poultry handling","desc":"Keep uncooked poultry separate from ready-to-eat food, wash hands and utensils after handling, and cook the chicken thoroughly before serving."}]},{"id":"rcp-allergy-chicken-and-cabbage-soup-with-rice","name":"Chicken and Cabbage Soup with Rice","type":"Dinner","cookTime":35,"dietTags":["dairy_free"],"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0776","name":"Chicken breast","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":50,"quantity":"50 g before cooking"},{"fct_id":"1503","name":"Ginger","grams":5,"quantity":"5 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":3,"quantity":"3 g before cooking"}],"steps":[{"title":"Measure raw inputs","desc":"60 g Rice, well-milled; 100 g Chicken breast; 100 g Cabbage, green; 50 g Carrot; 5 g Ginger; 3 g Oil, coconut. Weigh these ingredients before cooking. Use only the listed ingredients and plain water."},{"title":"Prepare the meal","desc":"Cook the measured dry rice separately in plain water. Simmer diced chicken breast and ginger in plain water until fully cooked. Add cabbage and carrot, cook until tender and stir in the measured coconut oil. Serve with all of the rice. This is a simple nilaga adaptation."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is estimated from the weighed ingredient inputs; final cooked output has not been measured."},{"title":"Ingredient and allergy review","desc":"Research formulation awaiting nutritionist review. Check supplier labels and avoid cross-contact during preparation. This recipe is not certified allergen-free or medically approved. Unlisted additions require a new ingredient check."},{"title":"Poultry handling","desc":"Keep uncooked poultry separate from ready-to-eat food, wash hands and utensils after handling, and cook the chicken thoroughly before serving."}]},{"id":"rcp-allergy-squash-rice-porridge","name":"Squash Rice Porridge","type":"Breakfast","cookTime":30,"dietTags":["vegan","vegetarian","dairy_free"],"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0491","name":"Squash fruit","grams":120,"quantity":"120 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":3,"quantity":"3 g before cooking"}],"steps":[{"title":"Measure raw inputs","desc":"60 g Rice, well-milled; 120 g Squash fruit; 3 g Oil, coconut. Weigh these ingredients before cooking. Use only the listed ingredients and plain water."},{"title":"Prepare the meal","desc":"Simmer the measured dry rice and diced squash in about 400 ml plain water until soft. Mash some squash into the porridge and stir in the measured coconut oil. This is a vegetable lugaw adaptation."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is estimated from the weighed ingredient inputs; final cooked output has not been measured."},{"title":"Ingredient and allergy review","desc":"Research formulation awaiting nutritionist review. Check supplier labels and avoid cross-contact during preparation. This recipe is not certified allergen-free or medically approved. Unlisted additions require a new ingredient check."}]},{"id":"rcp-allergy-sauteed-chayote-and-carrots-with-rice","name":"Sauteed Chayote and Carrots with Rice","type":"Lunch","cookTime":30,"dietTags":["vegan","vegetarian","dairy_free"],"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":75,"quantity":"75 g before cooking"},{"fct_id":"0323","name":"Chayote fruit","grams":150,"quantity":"150 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":50,"quantity":"50 g before cooking"},{"fct_id":"0355","name":"Garlic bulb","grams":3,"quantity":"3 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":5,"quantity":"5 g before cooking"}],"steps":[{"title":"Measure raw inputs","desc":"75 g Rice, well-milled; 150 g Chayote fruit; 50 g Carrot; 3 g Garlic bulb; 5 g Oil, coconut. Weigh these ingredients before cooking. Use only the listed ingredients and plain water."},{"title":"Prepare the meal","desc":"Cook the measured dry rice separately with plain water. Warm the measured oil, soften chopped garlic, then add sliced chayote and carrot. Add a little plain water and cook until tender. Serve with all of the rice. This is a ginisang sayote adaptation."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is estimated from the weighed ingredient inputs; final cooked output has not been measured."},{"title":"Ingredient and allergy review","desc":"Research formulation awaiting nutritionist review. Check supplier labels and avoid cross-contact during preparation. This recipe is not certified allergen-free or medically approved. Unlisted additions require a new ingredient check."}]},{"id":"rcp-allergy-squash-and-cabbage-soup-with-rice","name":"Squash and Cabbage Soup with Rice","type":"Dinner","cookTime":30,"dietTags":["vegan","vegetarian","dairy_free"],"ingredients":[{"fct_id":"0017","name":"Rice, well-milled","grams":60,"quantity":"60 g before cooking"},{"fct_id":"0491","name":"Squash fruit","grams":150,"quantity":"150 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":80,"quantity":"80 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":4,"quantity":"4 g before cooking"}],"steps":[{"title":"Measure raw inputs","desc":"60 g Rice, well-milled; 150 g Squash fruit; 80 g Cabbage, green; 4 g Oil, coconut. Weigh these ingredients before cooking. Use only the listed ingredients and plain water."},{"title":"Prepare the meal","desc":"Cook the measured dry rice separately with plain water. Simmer diced squash in plain water until tender, add cabbage and cook through. Stir in the measured coconut oil and serve with all of the rice. This is a sinabawang gulay adaptation."},{"title":"Serve one portion","desc":"Serve the entire prepared batch as one serving. Nutrition is estimated from the weighed ingredient inputs; final cooked output has not been measured."},{"title":"Ingredient and allergy review","desc":"Research formulation awaiting nutritionist review. Check supplier labels and avoid cross-contact during preparation. This recipe is not certified allergen-free or medically approved. Unlisted additions require a new ingredient check."}]}]$recipes$::jsonb) LOOP
    IF EXISTS (SELECT 1 FROM public.recipes WHERE name = r->>'name' OR id = r->>'id') THEN CONTINUE; END IF;
    SELECT count(*) INTO missing FROM jsonb_array_elements(r->'ingredients') ingredient
      WHERE NOT EXISTS(SELECT 1 FROM public.fnri_food_composition f WHERE f.fct_id = ingredient->>'fct_id');
    IF missing > 0 THEN RAISE EXCEPTION 'Required FNRI raw ingredient missing'; END IF;
    INSERT INTO public.recipes(id,name,type,difficulty,cook_time_min,servings,cost,kcal,protein_g,carbs_g,fats_g,diet_tags,goal_tags)
      SELECT r->>'id',r->>'name',r->>'type','easy',(r->>'cookTime')::integer,1,0,
       round(sum(f.energy_kcal * (ingredient->>'grams')::numeric / 100)),
       round(sum(f.protein_g * (ingredient->>'grams')::numeric / 100),1),
       round(sum(f.available_carbohydrate_g * (ingredient->>'grams')::numeric / 100),1),
       round(sum(f.total_fat_g * (ingredient->>'grams')::numeric / 100),1),
       ARRAY(SELECT jsonb_array_elements_text(r->'dietTags')), ARRAY['improve_health','maintain']::text[]
      FROM jsonb_array_elements(r->'ingredients') ingredient JOIN public.fnri_food_composition f ON f.fct_id=ingredient->>'fct_id'
      RETURNING id INTO recipe_id_new;
    INSERT INTO public.recipe_ingredients(recipe_id,fct_id,name,grams,quantity,status,sort_order)
      SELECT recipe_id_new,ingredient->>'fct_id',ingredient->>'name',(ingredient->>'grams')::numeric,ingredient->>'quantity','avail',ordinality::integer-1
      FROM jsonb_array_elements(r->'ingredients') WITH ORDINALITY AS t(ingredient,ordinality);
    INSERT INTO public.recipe_steps(recipe_id,title,description,step_order)
      SELECT recipe_id_new,step->>'title',step->>'desc',ordinality::integer-1
      FROM jsonb_array_elements(r->'steps') WITH ORDINALITY AS t(step,ordinality);
    INSERT INTO public.recipe_steps(recipe_id,title,description,step_order) VALUES(recipe_id_new,'Nutrition and costing basis','Research recipe awaiting nutritionist review. Nutrition is estimated from the listed FNRI raw ingredient inputs, not measured cooked output. Price excludes cooking water, fuel, labour and any unlisted additions. Divide the prepared batch only if you also divide the displayed portion.',99);
  END LOOP;
END $seed$;
COMMIT;
SELECT name,type,kcal FROM public.recipes WHERE id IN ('rcp-allergy-chicken-rice-porridge','rcp-allergy-ginger-chicken-and-chayote-with-rice','rcp-allergy-chicken-and-cabbage-soup-with-rice','rcp-allergy-squash-rice-porridge','rcp-allergy-sauteed-chayote-and-carrots-with-rice','rcp-allergy-squash-and-cabbage-soup-with-rice') ORDER BY type;
